CREATE TABLE catalog_profiles(material_id TEXT PRIMARY KEY REFERENCES materials(id), tenant TEXT NOT NULL, identity_key TEXT NOT NULL, attributes TEXT NOT NULL, verification TEXT NOT NULL CHECK(verification IN ('provisional','reviewed')), high_use INTEGER NOT NULL DEFAULT 0, preferred_product_id TEXT, UNIQUE(tenant,identity_key));
CREATE TABLE manufacturers(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, name TEXT NOT NULL, normalized TEXT NOT NULL, UNIQUE(tenant,normalized));
CREATE TABLE manufacturer_products(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), manufacturer_id TEXT NOT NULL REFERENCES manufacturers(id), part_number TEXT NOT NULL, normalized_part TEXT NOT NULL, title TEXT NOT NULL, source_url TEXT NOT NULL, verification TEXT NOT NULL CHECK(verification IN ('provisional','reviewed')), active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant,manufacturer_id,normalized_part));
CREATE TABLE translations(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), phrase TEXT NOT NULL, normalized TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('user_selection','ai_generated','admin_reviewed','ai_import')), actor TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, batch_id TEXT, UNIQUE(tenant,material_id,normalized,origin));
CREATE INDEX translation_lookup ON translations(tenant,normalized);
CREATE TABLE selection_events(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, actor TEXT NOT NULL, project TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), product_id TEXT REFERENCES manufacturer_products(id), phrase TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant,id));
CREATE TABLE job_restrictions(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, project TEXT NOT NULL, material_id TEXT REFERENCES materials(id), category TEXT, enabled INTEGER NOT NULL DEFAULT 0, manufacturer_ids TEXT NOT NULL, product_ids TEXT NOT NULL);
CREATE TABLE catalog_batches(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, digest TEXT NOT NULL, state TEXT NOT NULL, csv TEXT NOT NULL, report TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant,digest));
CREATE TABLE image_references(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), product_id TEXT REFERENCES manufacturer_products(id), source_url TEXT NOT NULL, rights_basis TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', batch_id TEXT);
ALTER TABLE draft_lines ADD COLUMN purchasing TEXT;
ALTER TABLE image_associations ADD COLUMN product_id TEXT REFERENCES manufacturer_products(id);
